import { expect, test, uniqueName } from "../../fixtures";

const W9_TEXT = "Legal Name: Acme Freight LLC\nTax ID: 12-3456789\nBusiness Type: LLC\n";

test("submitting with missing documents lists what is missing", { tag: "@REV-02" }, async ({ apiAs }) => {
  // Arrange
  const member = await apiAs("member");
  const createRes = await member.post("/api/vendors", {
    data: { name: uniqueName("REV-02 Vendor"), category: "logistics", contact_email: "ops@rev02.example" },
  });
  expect(createRes.status(), await createRes.text()).toBe(201);
  const vendor = await createRes.json();

  const uploadRes = await member.post(`/api/vendors/${vendor.id}/documents`, {
    multipart: {
      kind: "w9",
      file: { name: "w9.txt", mimeType: "text/plain", buffer: Buffer.from(W9_TEXT) },
    },
  });
  expect(uploadRes.status(), await uploadRes.text()).toBe(201);
  const document = await uploadRes.json();

  await expect
    .poll(async () => {
      const res = await member.get(`/api/documents/${document.id}`);
      return (await res.json()).status;
    }, { timeout: 30_000 })
    .toBe("extracted");

  // Act
  const response = await member.post(`/api/vendors/${vendor.id}/submit`);

  // Assert
  const body = await response.text();
  expect(response.status(), body).toBe(409);
  const error = JSON.parse(body).error;
  expect(error.code, body).toBe("documents_incomplete");
  expect(error.missing_kinds, body).toEqual(["contract", "insurance_certificate"]);
});
